开一个新坑（我就是这种喜欢开很多坑然后三分钟热度的人😭
From MIT 6.5840 / Spring 2024, Lab1 - MapReduce
MapReduce Paper: http://research.google.com/archive/mapreduce-osdi04.pdf
Pre Handle # 在 src/main/ 目录下，已经给出了sequential版本的实现: mrsequential.go(只需要运行该文件就可以完成sequential mapreduce).
在这个目录下还有两个文件 mrcoordinator.go &amp; mrworker.go，它们会调用 src/mr/ 目录下的 coordinator.go和worker.go文件中的函数来完成分片模拟下的mapreduce的处理。
我们可以观察一下mrcoordinator.go 和 mrworker.go这两个文件：
// mrcoordinator.go func main() { if len(os.Args) &lt; 2 { fmt.Fprintf(os.Stderr, &#34;Usage: mrcoordinator inputfiles...\n&#34;) os.Exit(1) } m := mr.MakeCoordinator(os.Args[1:], 10) for m.Done() == false { time.Sleep(time.Second) } time.Sleep(time.Second) } coordinator主要的执行逻辑就是初始化-&gt;轮询直到任务执行结束
//mrworker.go func main() { if len(os.Args) != 2 { fmt.Fprintf(os.Stderr, &#34;Usage: mrworker xxx.so\n&#34;) os.Exit(1) } mapf, reducef := loadPlugin(os.Args[1]) mr.Worker(mapf, reducef) } // load the application Map and Reduce functions // from a plugin file, e.g. ../mrapps/wc.so func loadPlugin(filename string) (func(string, string) []mr.KeyValue, func(string, []string) string) { p, err := plugin.Open(filename) if err != nil { log.Fatalf(&#34;cannot load plugin %v&#34;, filename) } xmapf, err := p.Lookup(&#34;Map&#34;) if err != nil { log.Fatalf(&#34;cannot find Map in %v&#34;, filename) } mapf := xmapf.(func(string, string) []mr.KeyValue) xreducef, err := p.Lookup(&#34;Reduce&#34;) if err != nil { log.Fatalf(&#34;cannot find Reduce in %v&#34;, filename) } reducef := xreducef.(func(string, []string) string) return mapf, reducef } worker则是先load相应的map和reduce函数，然后调用Worker函数执行任务
我们在这个lab中需要完成的就是src/mr/ 目录下的 coordinator.go，worker.go，rpc.go.
Get Started! # 首先，我们需要确定coordinator需要记录哪些状态：
// coordinator.go type TaskStatus int const ( Unassigned TaskStatus = iota Assigned Completed Failed ) type TaskInfo struct { TaskStatus TaskStatus // Status of task TaskFile string // File to process Timestamp time.Time // Assigned time } type Coordinator struct { MapNum int // Number of map tasks, in this lab it is the number of input files ReduceNum int // Number of reduce tasks, in this lab it is the number of nReduce MapTasks []TaskInfo // Map tasks record ReduceTasks []TaskInfo // Reduce tasks record AllMapTaskCompleted bool // Flag to indicate if all map tasks are completed AllReduceTaskCompleted bool // Flag to indicate if all reduce tasks are completed Mutex sync.Mutex // Mutex to protect shared data } 以及worker和coordinator之间传递的message的状态:
// rpc.go type TaskType int const ( Map TaskType = iota Reduce Wait Exit ) type TaskCompleteStatus int const ( MapTaskSuccess TaskCompleteStatus = iota MapTaskFail ReduceTaskSuccess ReduceTaskFail ) type CoordinatorMsgReply struct { TaskID int // ID of task, when Map - map id and when Reduce - reduce id TaskType TaskType // Type of task - Map or Reduce File string // File to process ReduceNum int // Number of reduce tasks MapNum int // Number of map tasks } type WorkerMsgSend struct { TaskID int // ID of task TaskCompleteStatus TaskCompleteStatus // Status of task - completed or failed } 上图！ 可以看到待处理的文件首先根据map num分给worker进行处理，产生的intermediate文件根据reduce num进行split传给对应的worker进行处理(一般认为处理reduce的worker数量和reduce num相同).
对于coordinator来说，它的工作就是：初始化-&gt;等待worker请求任务的到来-&gt;分配任务-&gt;处理任务完成的消息-&gt;所有任务执行完后结束job。其中关于rpc接收消息的部门和启动coordinator的部分在给的代码中已经写好。
我们需要完成：初始化状态 + 处理worker两种类型的消息（请求任务/汇报任务完成）处理函数。
// coordinator.go // 初始化过程中，主要关注一下 map&amp;reduce tasks的设置 // PS：在这个项目中，map num定义为输入文件的数量，reduce num则由传入参数指定 func MakeCoordinator(files []string, nReduce int) *Coordinator { c := Coordinator{ MapNum: len(files), ReduceNum: nReduce, MapTasks: make([]TaskInfo, len(files)), ReduceTasks: make([]TaskInfo, nReduce), AllMapTaskCompleted: false, AllReduceTaskCompleted: false, Mutex: sync.Mutex{}, } // Initialize Coordinator for idx := range files { c.MapTasks[idx] = TaskInfo{ TaskFile: files[idx], TaskStatus: Unassigned, Timestamp: time.Now(), } } for idx := range c.ReduceTasks { c.ReduceTasks[idx] = TaskInfo{ TaskStatus: Unassigned, } } c.server() return &amp;c } /* * RPC handler for worker to request task */ func (c *Coordinator) RequestTask(sendMsg *WorkerMsgSend, replyMsg *CoordinatorMsgReply) error { c.Mutex.Lock() defer c.Mutex.Unlock() // Assign Map Task if !c.AllMapTaskCompleted { // Count completed map tasks completedMapTaskNum := 0 for id, taskInfo := range c.MapTasks { // 判断一个任务可以被分配的条件：从未被分配 or 已经被分配但是没有在限定时间内处理完毕 or 任务执行失败 if taskInfo.TaskStatus == Unassigned || taskInfo.TaskStatus == Failed || (taskInfo.TaskStatus == Assigned &amp;&amp; time.Since(taskInfo.Timestamp) &gt; 10*time.Second) { // Build reply message replyMsg.File = taskInfo.TaskFile replyMsg.MapNum = c.MapNum replyMsg.ReduceNum = c.ReduceNum replyMsg.TaskID = id replyMsg.TaskType = Map // Update map task record in coordinator c.MapTasks[id].TaskStatus = Assigned c.MapTasks[id].Timestamp = time.Now() return nil } else if taskInfo.TaskStatus == Completed { completedMapTaskNum++ } } if completedMapTaskNum == len(c.MapTasks) { c.AllMapTaskCompleted = true } else { // There are no available map tasks currently(some map tasks are still has Worker working on it) replyMsg.TaskType = Wait return nil } } // Assign Reduce Task if !c.AllReduceTaskCompleted { // Count completed reduce tasks completedReduceTaskNum := 0 for id, taskInfo := range c.ReduceTasks { if taskInfo.TaskStatus == Unassigned || taskInfo.TaskStatus == Failed || (taskInfo.TaskStatus == Assigned &amp;&amp; time.Since(taskInfo.Timestamp) &gt; 10*time.Second) { // Build reply message replyMsg.MapNum = c.MapNum replyMsg.ReduceNum = c.ReduceNum replyMsg.TaskID = id replyMsg.TaskType = Reduce // Update reduce task record in coordinator c.ReduceTasks[id].TaskStatus = Assigned c.ReduceTasks[id].Timestamp = time.Now() return nil } else if taskInfo.TaskStatus == Completed { completedReduceTaskNum++ } } if completedReduceTaskNum == len(c.ReduceTasks) { c.AllReduceTaskCompleted = true } else { // There are no available reduce tasks currently(some reduce tasks are still has Worker working on it) replyMsg.TaskType = Wait return nil } } // All the tasks are completed replyMsg.TaskType = Exit return nil } /* * RPC handler for worker to report task completion */ func (c *Coordinator) ReportTask(sendMsg *WorkerMsgSend, replyMsg *CoordinatorMsgReply) error { c.Mutex.Lock() defer c.Mutex.Unlock() id := sendMsg.TaskID if sendMsg.TaskCompleteStatus == MapTaskSuccess { c.MapTasks[id].TaskStatus = Completed } else if sendMsg.TaskCompleteStatus == MapTaskFail { c.MapTasks[id].TaskStatus = Failed } else if sendMsg.TaskCompleteStatus == ReduceTaskSuccess { c.ReduceTasks[id].TaskStatus = Completed } else if sendMsg.TaskCompleteStatus == ReduceTaskFail { c.ReduceTasks[id].TaskStatus = Failed } return nil } 对于worker来说，与coordinator相对应的，它就需要执行map/reduce任务。 在Worker函数中，我们通过循环让worker处于一直执行任务的状态，直到所有的任务处理完成。
// main/mrworker.go calls this function. func Worker(mapf func(string, string) []KeyValue, reducef func(string, []string) string) { for { sendMsg := WorkerMsgSend{} replyMsg := CoordinatorMsgReply{} call(&#34;Coordinator.RequestTask&#34;, &amp;sendMsg, &amp;replyMsg) switch replyMsg.TaskType { case Map: // Map Task MapTask(mapf, replyMsg.File, replyMsg.TaskID, replyMsg.ReduceNum) case Reduce: // Reduce Task ReduceTask(reducef, replyMsg.TaskID, replyMsg.MapNum) case Wait: time.Sleep(1 * time.Second) case Exit: os.Exit(0) default: time.Sleep(1 * time.Second) } } } 在执行任务函数的实现过程中，注意文件名生成的格式：
intermediate file的文件名格式遵循：mr-{taskID}-{reduceIdx} (taskID stands for map task ID, ReduceIdx stands for the ID of reduce machine AKA reduce task ID) output file的文件名格式遵循：mr-{mapIdx}-{taskID} (mapIdx stands for index in map num, taskID stands for reduce task ID AKA reduce index) 这两个文件命名比较绕，容易搞糊
// Map Task func MapTask(mapf func(string, string) []KeyValue, taskFile string, taskID int, reduceNum int) { // Open file file, err := os.Open(taskFile) if err != nil { log.Fatalf(&#34;cannot open %v&#34;, taskFile) return } // Read file content, err := io.ReadAll(file) if err != nil { log.Fatalf(&#34;cannot read %v&#34;, taskFile) return } file.Close() // Call mapf kva := mapf(taskFile, string(content)) // Create intermediate files intermediate := make([][]KeyValue, reduceNum) for i := 0; i &lt; reduceNum; i++ { intermediate[i] = []KeyValue{} } // Partition intermediate data for _, kv := range kva { reduceIdx := ihash(kv.Key) % reduceNum intermediate[reduceIdx] = append(intermediate[reduceIdx], kv) } // Write intermediate data to files // File name format: // mr-{taskID}-{reduceIdx} (taskID stands for map task ID, ReduceIdx stands for the ID of reduce machine AKA reduce task ID) for i := 0; i &lt; reduceNum; i++ { oname := fmt.Sprintf(&#34;mr-%v-%v&#34;, taskID, i) ofile, _ := os.Create(oname) enc := json.NewEncoder(ofile) for _, kv := range intermediate[i] { enc.Encode(kv) } ofile.Close() } // Report task completion sendMsg := WorkerMsgSend{ TaskID: taskID, TaskCompleteStatus: MapTaskSuccess, } replyMsg := CoordinatorMsgReply{} call(&#34;Coordinator.ReportTask&#34;, &amp;sendMsg, &amp;replyMsg) } func ReduceTask(reducef func(string, []string) string, taskID int, mapNum int) { // Load intermediate data - get all intermediate data from all map tasks which are hashed to this reduce task intermediate := []KeyValue{} for i := 0; i &lt; mapNum; i++ { oname := fmt.Sprintf(&#34;mr-%v-%v&#34;, i, taskID) file, err := os.Open(oname) if err != nil { log.Fatalf(&#34;cannot open %v&#34;, oname) return } dec := json.NewDecoder(file) for { var kv KeyValue if err := dec.Decode(&amp;kv); err != nil { break } intermediate = append(intermediate, kv) } file.Close() } // Sort intermediate data sort.Slice(intermediate, func(i, j int) bool { return intermediate[i].Key &lt; intermediate[j].Key }) // Write to output file oname := fmt.Sprintf(&#34;mr-out-%v&#34;, taskID) ofile, err := os.Create(oname) if err != nil { log.Fatalf(&#34;cannot create %v&#34;, oname) return } // Call reducef for i := 0; i &lt; len(intermediate); { j := i values := []string{} for j &lt; len(intermediate) &amp;&amp; intermediate[j].Key == intermediate[i].Key { values = append(values, intermediate[j].Value) j++ } output := reducef(intermediate[i].Key, values) fmt.Fprintf(ofile, &#34;%v %v\n&#34;, intermediate[i].Key, output) i = j } ofile.Close() // Report task completion sendMsg := WorkerMsgSend{ TaskID: taskID, TaskCompleteStatus: ReduceTaskSuccess, } replyMsg := CoordinatorMsgReply{} call(&#34;Coordinator.ReportTask&#34;, &amp;sendMsg, &amp;replyMsg) } Test and Grade # 执行测试：
